(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Не е нужно днес да свършиш всичко. Следващото малко нещо е достатъчно.\", \"Умората не е провал. Уморена си, защото всеки ден си до тях.\", \"Чиниите могат да почакат. Можеш да седнеш за пет минути.\", \"Зърнена закуска за вечеря пак се брои за нахранено семейство.\", \"Почивката не е нещо, което трябва да заслужиш. Можеш да си починеш точно сега.\", \"Някои дни победата е, че всички сте стигнали до лягане. Това е истинска победа.\", \"Правиш повече, отколкото някой вижда. Аз го виждам.\", \"Разхвърлян дом и обичани деца. Това е добра размяна.\", \"В труден ден най-доброто ти изглежда различно, но пак се брои.\", \"Едно дълбоко вдишване. Отпусни раменете. Справяш се.\", \"Нормално е днес да свалиш летвата. Можеш да я вдигнеш друг ден.\", \"Да поискаш помощ е проява на сила, не на слабост.\", \"Имаш право да кажеш „не“ на още едно нещо.\", \"Ако днес си се чувствала самотна, не си единствената майка, която го е усетила. Много сме.\", \"Заслужаваш приятелка, която да те попита как си и да изчака отговора.\", \"Нормално е ти да потърсиш първа. Повечето майки се надяват някой да го направи.\", \"Това, че се чувстваш невидима, не значи, че нямаш значение. Имаш огромно значение.\", \"Чувствата ти са разбираеми. Не си „прекалено“.\", \"Тук не е нужно да обясняваш трудния си ден. Разбираме те.\", \"Едно съобщение до друга майка с думите „и аз“ може да преобърне целия ден.\", \"Хранене, преповиване, люлеене и отначало. Това е истинска работа, дори когато изглежда като седене на едно място.\", \"Ти и бебето ти още се опознавате. Няма за къде да бързате.\", \"Дните с новородено са дълги. Този период няма да трае вечно.\", \"Ако днес единственото, което си направила, е да държиш едно мъничко човече нахранено и на топло, свършила си голяма работа.\", \"Не е нужно бързо да се върнеш във форма. Можеш просто да бъдеш там, където си.\", \"Както и да храниш бебето си, ти се грижиш за него. Това е важното.\", \"Можеш да си недоспала и пълна с обич едновременно.\", \"Гушни бебето и остави къщата. Къщата ще си е тук и после.\", \"Една криза в магазина не те прави лоша майка. Просто имаш малко дете.\", \"Малките проверяват границите, защото се чувстват в безопасност с теб.\", \"Днес остана спокойна с една минута по-дълго от вчера. Това се брои.\", \"Ако си избухнала, една прегръдка и едно „извинявай“ оправят много. И ги учат на нещо хубаво.\", \"Лепкави ръчички, силни гласове, големи чувства. Отглеждаш цял човек.\", \"Петото „защо?“ за един час е малко умче, което расте.\", \"Не ти трябва съвършен ден, за да създадеш щастлив спомен.\", \"Една затръшната врата не е краят на историята. Остави лампата да свети.\", \"Тийнейджърът ти може и да не го казва, но това, че винаги си до него, има значение.\", \"Да бъдеш спокойната вкъщи е тежка работа. А ти я вършиш.\", \"Някои от най-хубавите разговори се случват в колата. Карай нататък.\", \"Отдалечават се, за да пораснат, а не за да те оставят зад себе си.\", \"Не е нужно да знаеш всички отговори. Слушането е голяма част от това.\", \"Големите деца още имат нужда от теб, просто по по-тих начин.\", \"Да се справяш сама изисква сила, която повечето хора никога не виждат.\", \"Ти си достатъчно добра майка за детето си. Винаги си била.\", \"Едни ръце, сто задачи. Бъди по-мила към себе си.\", \"Като те гледат, децата ти научават как изглежда един силен и обичащ човек.\", \"Почивката не е изоставяне на поста ти. Тя е начинът да продължиш.\", \"Никой не брои точки. Важни са обичта и това, че си тук.\", \"Скръбта и любовта идват от едно и също място. Колкото ти липсва някой, толкова си го обичала.\", \"Няма правилен срок за скръбта. Дай си толкова време, колкото ти трябва.\", \"На тежките годишнини бъди толкова нежна към себе си, колкото би била към приятелка.\", \"Можеш да носиш тъга и пак да се смееш с децата си. И двете са истински.\", \"Ако си загубила бременност или бебе, тази загуба е истинска, както и твоята обич.\", \"Някои дни скръбта е тиха, а други – шумна. И двете са нормални.\", \"Малкото пари не означават малко обич.\", \"Децата ти ще помнят времето с теб повече от нещата, които си купила.\", \"Да попиташ за помощ със сметките е разумно, а не срамно. Точно за това е тази помощ.\", \"Един безплатен следобед в парка може да е най-хубавият ден от седмицата.\", \"Изкара с парите още една седмица. Това иска истинско умение.\", \"Тревогата за пари изтощава. Носиш много, и пак си тук.\", \"Днес изпи чаша вода. Започни оттам.\", \"Всички излязоха от вкъщи. Обувките може и да не си пасваха. Пак е победа.\", \"Направи обаждането, от което се страхуваше. Това беше смело.\", \"Днес се смя. Задръж това.\", \"Топла храна, чиста блузка, приказка за лека нощ. От малките неща се гради детството.\", \"Днес беше добра към някого, дори ако това беше само към себе си.\", \"Напредък, не съвършенство. Днес направи крачка напред.\", \"Свърши едно нещо от списъка. Това е с едно повече от нищо.\", \"Ти си добра майка. Това, че се тревожиш, показва колко много държиш на това.\", \"Ти си повече от това, което успяваш да свършиш за един ден.\", \"Децата ти нямат нужда от съвършена майка. Имат нужда от теб, и те имат.\", \"Бъди толкова търпелива към себе си, колкото си към децата си.\", \"Имаш право да заемаш място, да искаш нещо за себе си и да имаш свои мечти.\", \"Една грешка не заличава обичта. Утре е ново начало.\", \"Ти си целият свят за някого, но си и човек сама по себе си.\", \"Нормално е да не ти харесва всяка минута. Пак можеш да обичаш децата си с цялото си сърце.\", \"Няма един правилен начин да бъдеш майка. Твоят начин също е правилен.\", \"Като в позата на дървото, нормално е да се олюлееш. Можеш отново да намериш равновесие.\", \"Стъпи здраво като в позата на планината. По-стабилна си, отколкото се чувстваш.\", \"Воин две: силни крака, отворени ръце. Това си ти пред тази седмица.\", \"Вдишай на четири, издишай на четири. Тук си и се справяш.\", \"Разпери се широко като звезда. Имаш право да заемаш място.\", \"Широкият нисък клек се задържа трудно. Дългият ден също. А ти го задържаш.\", \"Можеш да се наклониш като полумесец и пак да стоиш права.\", \"Още не е нужно да стигаш пръстите на краката си. Всяко малко разтягане се брои.\", \"Позата на триъгълника: едната ръка долу, другата горе. Стой здраво на земята и продължавай да се протягаш.\", \"Късно е. Каквото не е свършено днес, може да почака до утре.\", \"Будна с бебето в този час? Много майки са будни с теб точно сега.\", \"Къщата е тиха. Този миг е твой. Дишай.\", \"Изкара деня. Това беше всичко, от което днешният ден имаше нужда.\", \"Ако умът ти не спира тази нощ, запиши мислите си и ги остави да почакат до сутринта.\", \"Затвори очи и си почини. Утре можеш да започнеш отначало.\", \"Празниците могат да са тежки, не само радостни. Каквото и да чувстваш през този сезон, то е нормално.\", \"Масата не е нужно да е съвършена. Важни са хората около нея.\", \"Ако тази година ти липсва някой на масата, бъди нежна със сърцето си.\", \"Благодаря ти, мамо, за всяко ястие, всяко возене и всяка прегръдка.\", \"Не е нужно да посрещаш гости, да печеш или да се усмихваш през цялото време. Простият празник пак е празник.\", \"Най-хубавият подарък, който децата ти ще получат тази година, е времето с теб.\", \"Малкият празник пак е пълен с обич. Не са нужни много пари, за да е специален.\", \"Студени дни, топли прегръдки. Ти си топлото място в своя дом.\", \"Нормално е да пропуснеш част от празничната суматоха. Спокойствието също е подарък.\", \"Ако тази година празниците ти тежат, не си сама. Ден по ден.\"]";D.body.appendChild(e)})();
